import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test complete todo retrieval workflow where a user creates a todo item and
 * then retrieves it by ID. Validates that users can only access their own todo
 * items, that the retrieved data matches the created data, and that all fields
 * including timestamps and status are correctly returned. Tests ownership
 * validation by ensuring users cannot access todos belonging to other users.
 */
export async function test_api_todo_retrieval_by_owner(
  connection: api.IConnection,
) {
  // Step 1: Create first user account using todoApp auth register
  const firstUserEmail = typia.random<string & tags.Format<"email">>();
  const firstUserPassword = "password123";

  const firstUser: ITodoAppUser =
    await api.functional.todoApp.auth.register.create(connection, {
      body: {
        email: firstUserEmail,
        password: firstUserPassword,
      } satisfies ITodoAppUser.ICreate,
    });
  typia.assert(firstUser);

  // Step 2: Create todo item for first user
  const todoTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 2,
    wordMax: 8,
  });
  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.user.users.todos.create(connection, {
      userId: firstUser.id,
      body: {
        title: todoTitle,
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(createdTodo);

  // Validate initial todo state
  TestValidator.equals(
    "todo title matches input",
    createdTodo.title,
    todoTitle,
  );
  TestValidator.equals(
    "todo status defaults to active",
    createdTodo.status,
    "active",
  );
  TestValidator.equals(
    "todo belongs to correct user",
    createdTodo.todo_app_user_id,
    firstUser.id,
  );
  TestValidator.predicate(
    "created_at timestamp is present",
    createdTodo.created_at !== null && createdTodo.created_at !== undefined,
  );
  TestValidator.predicate(
    "updated_at timestamp is present",
    createdTodo.updated_at !== null && createdTodo.updated_at !== undefined,
  );
  TestValidator.equals(
    "completed_at is null for new todo",
    createdTodo.completed_at,
    undefined,
  );
  TestValidator.equals(
    "deleted_at is null for active todo",
    createdTodo.deleted_at,
    undefined,
  );

  // Step 3: Retrieve the created todo
  const retrievedTodo: ITodoAppTodo =
    await api.functional.todoApp.user.users.todos.at(connection, {
      userId: firstUser.id,
      todoId: createdTodo.id,
    });
  typia.assert(retrievedTodo);

  // Validate retrieved todo matches created todo
  TestValidator.equals(
    "retrieved todo ID matches created todo",
    retrievedTodo.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "retrieved todo title matches",
    retrievedTodo.title,
    createdTodo.title,
  );
  TestValidator.equals(
    "retrieved todo status matches",
    retrievedTodo.status,
    createdTodo.status,
  );
  TestValidator.equals(
    "retrieved todo user ID matches",
    retrievedTodo.todo_app_user_id,
    createdTodo.todo_app_user_id,
  );
  TestValidator.equals(
    "retrieved todo created_at matches",
    retrievedTodo.created_at,
    createdTodo.created_at,
  );
  TestValidator.equals(
    "retrieved todo updated_at matches",
    retrievedTodo.updated_at,
    createdTodo.updated_at,
  );

  // Step 4: Create second user using fresh connection to avoid authentication conflicts
  const secondUserEmail = typia.random<string & tags.Format<"email">>();
  const secondUserPassword = "password456";

  const secondUserConnection: api.IConnection = { ...connection, headers: {} };

  const secondUser: ITodoAppUser =
    await api.functional.todoApp.auth.register.create(secondUserConnection, {
      body: {
        email: secondUserEmail,
        password: secondUserPassword,
      } satisfies ITodoAppUser.ICreate,
    });
  typia.assert(secondUser);

  // Step 5: Attempt to access first user's todo with second user's credentials (should fail)
  await TestValidator.error(
    "second user cannot access first user's todo",
    async () => {
      await api.functional.todoApp.user.users.todos.at(secondUserConnection, {
        userId: secondUser.id, // Second user's ID
        todoId: createdTodo.id, // First user's todo ID
      });
    },
  );

  // Step 6: Verify first user can still access their own todo
  const finalRetrievedTodo: ITodoAppTodo =
    await api.functional.todoApp.user.users.todos.at(connection, {
      userId: firstUser.id,
      todoId: createdTodo.id,
    });
  typia.assert(finalRetrievedTodo);
  TestValidator.equals(
    "final retrieved todo ID matches",
    finalRetrievedTodo.id,
    createdTodo.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test the complete user account deletion workflow including authentication,
 * ownership verification, and cascade deletion of associated data.
 *
 * This test validates that when a user account is deleted, all associated todo
 * items are properly removed through cascade deletion, and the system maintains
 * proper authentication and ownership verification throughout the process.
 */
export async function test_api_user_account_deletion_complete_workflow(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";

  const createdUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(createdUser);

  // Step 2: Authenticate the user to establish session
  const authenticatedUser = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
      href: "https://example.com/todo-app",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ILogin,
  });
  typia.assert(authenticatedUser);

  // Verify authentication token was set
  TestValidator.equals(
    "authentication token should be set",
    typeof connection.headers?.Authorization,
    "string",
  );

  // Step 3: Create multiple todo items for the user
  const todoTitles = [
    "Buy groceries",
    "Finish project",
    "Call dentist",
  ] as const;
  const createdTodos: ITodoAppTodo[] = [];

  for (const title of todoTitles) {
    const todo = await api.functional.todoApp.user.users.todos.create(
      connection,
      {
        userId: createdUser.id,
        body: {
          title: title,
        } satisfies ITodoAppTodo.ICreate,
      },
    );
    typia.assert(todo);
    createdTodos.push(todo);

    // Verify todo ownership
    TestValidator.equals(
      "todo should belong to the user",
      todo.todo_app_user_id,
      createdUser.id,
    );
  }

  // Step 4: Perform account deletion operation
  const deletedUser = await api.functional.todoApp.user.users.erase(
    connection,
    {
      userId: createdUser.id,
    },
  );
  typia.assert(deletedUser);

  // Step 5: Validate deletion response contains correct user information
  TestValidator.equals(
    "deleted user ID matches created user ID",
    deletedUser.id,
    createdUser.id,
  );
  TestValidator.equals(
    "deleted user email matches created user email",
    deletedUser.email,
    createdUser.email,
  );
  TestValidator.equals(
    "deleted user status should be active",
    deletedUser.status,
    "active",
  );

  // Step 6: Verify cascade deletion - todos should no longer be accessible
  for (const todo of createdTodos) {
    await TestValidator.error(
      `should not be able to access todo ${todo.id} after user deletion`,
      async () => {
        // Attempt to perform any operation with the deleted todo
        // This should fail due to cascade deletion
        await api.functional.todoApp.user.users.todos.create(connection, {
          userId: createdUser.id, // This user no longer exists
          body: {
            title: "This should fail",
          } satisfies ITodoAppTodo.ICreate,
        });
      },
    );
  }

  // Step 7: Verify authentication is cleared after deletion
  await TestValidator.error(
    "should not be able to authenticate with deleted user credentials",
    async () => {
      await api.functional.auth.user.login(connection, {
        body: {
          email: userEmail,
          password: userPassword,
          href: "https://example.com/todo-app",
          referrer: "https://example.com",
        } satisfies ITodoAppUser.ILogin,
      });
    },
  );

  // Step 8: Verify ownership - different user cannot delete this account
  // Create a second user
  const secondUserEmail = typia.random<string & tags.Format<"email">>();
  const secondUser = await api.functional.auth.user.join(connection, {
    body: {
      email: secondUserEmail,
      password: "anotherPassword123",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(secondUser);

  // Authenticate as second user
  await api.functional.auth.user.login(connection, {
    body: {
      email: secondUserEmail,
      password: "anotherPassword123",
      href: "https://example.com/todo-app",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ILogin,
  });

  // Second user should not be able to delete the first user's account
  await TestValidator.error(
    "different user cannot delete another user's account",
    async () => {
      await api.functional.todoApp.user.users.erase(connection, {
        userId: createdUser.id, // Trying to delete first user's account
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatus";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Comprehensive todo search functionality test with filtering, pagination, and
 * sorting.
 *
 * This test validates the complete todo search workflow including:
 *
 * - User authentication and todo creation
 * - Status-based filtering (active vs completed)
 * - Text search functionality in todo titles
 * - Pagination with different page sizes
 * - Sorting by various fields
 * - Pagination metadata validation
 * - User isolation (ensuring only authenticated user's todos are accessible)
 */
export async function test_api_user_todo_search_filtering_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = "testPassword123";

  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create multiple todo items with different statuses and titles
  const todoTitles = [
    "Buy groceries for the week",
    "Complete project documentation",
    "Call client about meeting schedule",
    "Review code changes",
    "Prepare presentation slides",
    "Schedule team building activity",
    "Update project timeline",
    "Research new technologies",
    "Write unit tests",
    "Deploy application to production",
  ] as const;

  const createdTodos: ITodoAppTodo[] = [];

  for (let i = 0; i < todoTitles.length; i++) {
    const todo = await api.functional.todoApp.user.users.todos.create(
      connection,
      {
        userId: user.id,
        body: {
          title: todoTitles[i],
        } satisfies ITodoAppTodo.ICreate,
      },
    );
    typia.assert(todo);
    createdTodos.push(todo);
  }

  // Step 3: Test status filtering - all todos should be active by default
  const activeTodosResponse =
    await api.functional.todoApp.user.users.todos.index(connection, {
      userId: user.id,
      body: {
        status: "active",
      } satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(activeTodosResponse);

  TestValidator.equals(
    "active todos should include all created todos",
    activeTodosResponse.data.length,
    createdTodos.length,
  );

  // Test that completed status returns empty (since no todos are completed)
  const completedTodosResponse =
    await api.functional.todoApp.user.users.todos.index(connection, {
      userId: user.id,
      body: {
        status: "completed",
      } satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(completedTodosResponse);

  TestValidator.equals(
    "completed todos should be empty since none are marked completed",
    completedTodosResponse.data.length,
    0,
  );

  // Step 4: Test text search functionality
  const searchResponse = await api.functional.todoApp.user.users.todos.index(
    connection,
    {
      userId: user.id,
      body: {
        search: "project",
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(searchResponse);

  TestValidator.predicate(
    "search should return todos containing 'project' in title",
    searchResponse.data.length > 0 &&
      searchResponse.data.every((todo) =>
        todo.title.toLowerCase().includes("project"),
      ),
  );

  // Test search with non-matching term
  const emptySearchResponse =
    await api.functional.todoApp.user.users.todos.index(connection, {
      userId: user.id,
      body: {
        search: "nonexistentterm",
      } satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(emptySearchResponse);

  TestValidator.equals(
    "search with non-matching term should return empty results",
    emptySearchResponse.data.length,
    0,
  );

  // Step 5: Test pagination with different page sizes
  const pageSize = 3;
  const paginatedResponse = await api.functional.todoApp.user.users.todos.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: pageSize,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(paginatedResponse);

  TestValidator.equals(
    "pagination should return correct number of items per page",
    paginatedResponse.data.length,
    Math.min(pageSize, createdTodos.length),
  );

  TestValidator.equals(
    "pagination metadata should show correct total records",
    paginatedResponse.pagination.records,
    createdTodos.length,
  );

  TestValidator.equals(
    "pagination metadata should show correct current page",
    paginatedResponse.pagination.current,
    1,
  );

  TestValidator.equals(
    "pagination metadata should show correct limit",
    paginatedResponse.pagination.limit,
    pageSize,
  );

  // Step 6: Test sorting options
  const sortedByCreatedAt = await api.functional.todoApp.user.users.todos.index(
    connection,
    {
      userId: user.id,
      body: {
        order_by: "created_at",
        order_direction: "desc",
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(sortedByCreatedAt);

  TestValidator.predicate(
    "sorted response should contain todos",
    sortedByCreatedAt.data.length > 0,
  );

  // Step 7: Test combination of filters
  const combinedFilterResponse =
    await api.functional.todoApp.user.users.todos.index(connection, {
      userId: user.id,
      body: {
        search: "project",
        status: "active",
        order_by: "title",
        order_direction: "asc",
      } satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(combinedFilterResponse);

  // Step 8: Validate that only authenticated user's todos are accessible
  // Create a second user with a fresh connection to avoid authentication conflicts
  const secondUserConnection: api.IConnection = { ...connection, headers: {} };
  const secondUserEmail = typia.random<string & tags.Format<"email">>();

  const secondUser = await api.functional.auth.user.join(secondUserConnection, {
    body: {
      email: secondUserEmail,
      password: "anotherPassword123",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(secondUser);

  // Verify second user has no todos initially
  const secondUserTodos = await api.functional.todoApp.user.users.todos.index(
    secondUserConnection,
    {
      userId: secondUser.id,
      body: {} satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(secondUserTodos);

  TestValidator.equals(
    "second user should have no todos initially",
    secondUserTodos.data.length,
    0,
  );

  // Verify first user still has all their todos (using original connection)
  const firstUserTodosAfterSwitch =
    await api.functional.todoApp.user.users.todos.index(connection, {
      userId: user.id,
      body: {} satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(firstUserTodosAfterSwitch);

  TestValidator.equals(
    "first user should still have all their todos",
    firstUserTodosAfterSwitch.data.length,
    createdTodos.length,
  );
}

